        assert.throws(() => { obj.name = "simba"; }, TypeError);

        // ----- array -----
        const arrSchema = zod.array(zod.string()).readonly();
        const arr = arrSchema.parse(["a", "b"]);
        assert.deepStrictEqual(arr, ["a", "b"]);
