        const set = setSchema.parse(new Set(["a", "b"]));
        assert.ok(set instanceof Set);
        assert.ok(set.has("a"));
        assert.ok(Object.isFrozen(set), "set should be frozen");
        // Similar to Map, Set contents can still be mutated after Object.freeze.
        set.add("c");
