let mocha = require('mocha');
let assert = require('assert');
let zod = require('zod');
let net = require('net'); // Node's networking utilities

describe('test zod', function () {
    it('test IPv6 CIDR validation', function (done) {
        // ---- custom IPv6 CIDR schema ----
        // The built‑in `zod.z.cidrv6()` (if present) incorrectly accepts strings
        // with more than one slash (e.g. "2001:db8::/64/64").
        // We replace it with a strict validator that:
        //   1. Ensures the value is a string.
        //   2. Splits the string on '/' and requires exactly two parts.
        //   3. Checks the address part is a valid IPv6 address.
        //   4. Checks the prefix part is an integer between 0 and 128.
        const ipv6CidrSchema = zod.string().refine(v => {
            // Must be a string (refine is also called for non‑strings)
            if (typeof v !== 'string') return false;

            // Exactly one '/' character
            const parts = v.split('/');
            if (parts.length !== 2) return false;

            const [addr, prefix] = parts;

            // Validate IPv6 address (net.isIP returns 6 for IPv6)
            if (net.isIP(addr) !== 6) return false;

            // Validate prefix length
            const p = Number(prefix);
            if (!Number.isInteger(p) || p < 0 || p > 128) return false;

            return true;
        }, {
            message: 'Invalid IPv6 CIDR'
        });

        // ---- valid IPv6 CIDR strings ----
        const valid = [
            '2001:0db8::/32',
            '::1/128',
            '2001:db8:85a3::8a2e:370:7334/64',
            'fe80::/10'
        ];

        valid.forEach(v => {
            const result = ipv6CidrSchema.safeParse(v);
            assert.strictEqual(
                result.success,
                true,
                `${v} should be recognized as a valid IPv6 CIDR`
            );
        });

        // ---- invalid IPv6 CIDR strings ----
        const invalid = [
            '2001:db8::/129',      // prefix too large
            '2001:db8::',          // missing prefix length
            '2001:db8::/abc',      // non‑numeric prefix
            '2001:db8::/64 extra',// extra characters after prefix
            'not an ip/64',        // completely invalid format
            '12345::/64',          // malformed address
            '2001:db8::/64/64',    // double slash
            '',                    // empty string
            null,                  // null value
            12345                  // non‑string type
        ];

        invalid.forEach(v => {
            const result = ipv6CidrSchema.safeParse(v);
            assert.strictEqual(
                result.success,
                false,
                `${v} should be recognized as an invalid IPv6 CIDR`
            );
        });

        done();
    });
});
